// Load the tickets and the knowledge base. One item out per ticket.
const fs = require('fs');
const path = require('path');
const base = $env.EP03_DIR;
const faq = fs.readFileSync(path.join(base, 'data', 'faq.md'), 'utf8');
const raw = fs.readFileSync(path.join(base, 'data', 'tickets.csv'), 'utf8');
const [header, ...lines] = raw.trim().split('\n');
return lines.map((line) => {
  const m = line.match(/^([^,]+),([^,]+),([^,]+),"(.*)"$/);
  return { json: { ticket_id: m[1], customer: m[2], subject: m[3], body: m[4], faq } };
});

// Ask the model. It may ONLY answer from the knowledge base, and it must
// cite which entry it used — no citation, no answer.
const https = require('https');

const ask = (payload) => new Promise((resolve, reject) => {
  const body = JSON.stringify(payload);
  const req = https.request({
    hostname: 'fal.run', path: '/fal-ai/any-llm', method: 'POST',
    headers: {
      'Authorization': 'Key ' + $env.FAL_KEY,
      'Content-Type': 'application/json',
      'Content-Length': Buffer.byteLength(body),
    },
  }, (res) => {
    let data = '';
    res.on('data', (c) => (data += c));
    res.on('end', () => resolve(JSON.parse(data)));
  });
  req.on('error', reject);
  req.write(body);
  req.end();
});

const out = [];
for (const item of $input.all()) {
  const t = item.json;
  const res = await ask({
    model: 'meta-llama/llama-4-scout',
    system_prompt:
      'You are a support agent. Answer ONLY from the knowledge base. ' +
      'Reply as JSON: {"citation": "<TAG or NONE>", "answer": "<reply or ESCALATE>"}. ' +
      'If no knowledge-base entry answers the ticket, citation must be NONE and answer ESCALATE.\n\n' +
      'KNOWLEDGE BASE:\n' + t.faq,
    prompt: 'TICKET from ' + t.customer + ' (' + t.subject + '): ' + t.body,
  });
  let verdict;
  try { verdict = JSON.parse((res.output ?? '').replace(/```json|```/g, '').trim()); }
  catch { verdict = { citation: 'NONE', answer: 'ESCALATE' }; }
  out.push({ json: { ticket_id: t.ticket_id, customer: t.customer, subject: t.subject, ...verdict } });
}
return out;

// The gate, and the receipts. No citation = a human gets the ticket.
const fs = require('fs');
const path = require('path');
const dir = path.join($env.EP03_DIR, 'out');
fs.mkdirSync(dir, { recursive: true });

const answered = [];
const escalated = [];
for (const { json: r } of $input.all()) {
  const ok = r.citation && r.citation !== 'NONE' && r.answer !== 'ESCALATE';
  (ok ? answered : escalated).push(r);
}
fs.writeFileSync(path.join(dir, 'answered.json'), JSON.stringify(answered, null, 2));
fs.writeFileSync(path.join(dir, 'escalated.json'), JSON.stringify(escalated, null, 2));
const summary = {
  tickets: answered.length + escalated.length,
  answered: answered.length,
  escalated: escalated.length,
  rate: Math.round((answered.length / (answered.length + escalated.length)) * 100) + '%',
};
fs.writeFileSync(path.join(dir, 'summary.json'), JSON.stringify(summary, null, 2));
return [{ json: summary }];
